function isSessionComplete() {
  return !!session?.ids.length && session.ids.every((id, index) => !!session.answers[index]);
}

function showSessionResult() {
  if (!isSessionComplete()) return;
  session.index = session.ids.length;
  route = 'result';
  render();
}

